<script>
// ============================================================
//  WASTED TOKEN MINT — COIN RENDERER
//  Pure canvas 2D — fully procedural, no external deps
// ============================================================

(function() {
'use strict';

// ---------- MATH HELPERS ----------
const TAU = Math.PI * 2;
const lerp = (a, b, t) => a + (b - a) * t;
const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const smoothstep = (a, b, t) => { const x = clamp((t-a)/(b-a),0,1); return x*x*(3-2*x); }

// ---------- HERO CANVAS ----------
const heroCanvas = document.getElementById('coin-hero');
const hctx = heroCanvas.getContext('2d');
const W = 420, H = 420;
heroCanvas.width = W;
heroCanvas.height = H;

// Animation state
let animRunning = true;
let startTime = null;
const LOOP_DURATION = 4000; // ms

// setTime API — t in [0,1]
function renderAtT(t) {
  // Combined rotation:
  //   yaw (spin about vertical): full 360 over loop
  //   pitch (flip about horizontal): one 180-flip and back over loop
  const yawAngle   = t * TAU;
  const pitchAngle = Math.sin(t * TAU) * Math.PI * 0.55;
  drawCoin(hctx, W/2, H/2, 160, yawAngle, pitchAngle, 'hero');
}

// ---------- COIN DRAWING ENGINE ----------
function drawCoin(ctx, cx, cy, R, yaw, pitch, mode) {
  ctx.clearRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  // Background
  const bgGrad = ctx.createRadialGradient(cx, cy-20, 10, cx, cy, ctx.canvas.height*0.7);
  bgGrad.addColorStop(0, '#1a1a28');
  bgGrad.addColorStop(1, '#08080f');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, ctx.canvas.width, ctx.canvas.height);

  // Which face?  cos(yaw) drives the face flip (like a coin spinning)
  // We also account for pitch
  const faceNormal = Math.cos(yaw); // +1 = front, -1 = back
  const showFront = faceNormal >= 0;

  // Projected ellipse axes
  // yaw squishes horizontal axis (like turning coin left-right)
  // pitch squishes vertical axis (flipping)
  const scaleX = Math.abs(Math.cos(yaw));  // 0..1, coin narrows as it turns
  const scaleY = Math.abs(Math.cos(pitch)); // 0..1, coin narrows as it flips

  const rx = Math.max(R * scaleX, 2); // horizontal semi-axis
  const ry = Math.max(R * scaleY, 2); // vertical semi-axis (slight perspective)
  // Make vertical a bit thicker for realism
  const ryActual = Math.max(ry * 0.96 + R * 0.04, 2);

  // ---- COIN PARAMS BY MODE ----
  let coinParams = getCoinParams(mode, ctx.canvas.width, ctx.canvas.height);

  // ---- EDGE / RIM ----
  drawCoinEdge(ctx, cx, cy, R, rx, ryActual, yaw, pitch, coinParams);

  // ---- FACE ----
  drawCoinFace(ctx, cx, cy, R, rx, ryActual, yaw, pitch, showFront, coinParams);

  // ---- SPECULAR HIGHLIGHT ----
  drawSpecular(ctx, cx, cy, R, rx, ryActual, yaw, pitch);
}

function getCoinParams(mode, cw, ch) {
  const params = {
    hero:   { primary: '#c8a84b', secondary: '#8b6b2a', dark: '#5a3d10', light: '#f0d878', rim: '#a07030', rimDark: '#6b4820' },
    bronze: { primary: '#cd7f32', secondary: '#8b5e20', dark: '#5a3508', light: '#e8a050', rim: '#9b5f22', rimDark: '#6b3a10' },
    silver: { primary: '#c0c0c8', secondary: '#808090', dark: '#404050', light: '#f0f0ff', rim: '#a0a0b0', rimDark: '#606070' },
    gold:   { primary: '#ffd700', secondary: '#c8a000', dark: '#805000', light: '#fff080', rim: '#e8c000', rimDark: '#a07800' },
    black:  { primary: '#303040', secondary: '#181820', dark: '#080810', light: '#606080', rim: '#282830', rimDark: '#101018' },
  };
  return params[mode] || params.hero;
}

function drawCoinEdge(ctx, cx, cy, R, rx, ryActual, yaw, pitch, p) {
  // Edge thickness: proportional to coin thinness on screen
  const edgeThickness = clamp(14 * (1 - Math.abs(Math.cos(yaw)) * 0.7), 2, 14);
  if (edgeThickness < 1) return;

  // Reeded edge: draw as stacked lines along the rim
  const REEDS = 120;
  const edgeVisible = Math.abs(Math.sin(yaw)); // how much edge is visible

  if (edgeVisible < 0.05) return;

  ctx.save();

  // Clip to edge band (between outer and inner ellipse)
  const outerRx = rx + edgeThickness;
  const outerRy = ryActual + edgeThickness * 0.3;

  // Draw reeded texture
  for (let i = 0; i < REEDS; i++) {
    const angle = (i / REEDS) * TAU;
    // Only draw reeds that are on the visible side
    const reedAngleFromFront = angle; // angle around coin circumference
    const sideX = Math.cos(reedAngleFromFront);
    // which side of coin is this reed? 
    const viewDot = sideX * Math.sin(yaw); // positive = facing camera side
    if (viewDot < 0) continue; // back-face cull reeds

    const brightness = 0.4 + viewDot * 0.6;
    const isRidge = (i % 2 === 0);

    const ex = cx + Math.cos(reedAngleFromFront) * outerRx;
    const ey = cy + Math.sin(reedAngleFromFront) * outerRy;

    const c = isRidge ? p.light : p.dark;
    const alpha = clamp(brightness * 0.9, 0, 1);

    ctx.beginPath();
    ctx.arc(ex, ey, edgeThickness * 0.45 + (isRidge ? 0.5 : 0), 0, TAU);

    // Color the reed
    const lv = isRidge ? 1.2 : 0.6;
    ctx.fillStyle = colorMult(c, brightness * lv, alpha);
    ctx.fill();
  }

  ctx.restore();
}

function drawCoinFace(ctx, cx, cy, R, rx, ryActual, yaw, pitch, showFront, p) {
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx, ryActual, 0, 0, TAU);
  ctx.clip();

  // Base metal gradient
  const lightX = cx - rx * 0.3 * Math.sin(yaw * 0.5);
  const lightY = cy - ryActual * 0.4;

  const metalGrad = ctx.createRadialGradient(lightX - 20, lightY - 20, 5, cx, cy, R * 1.1);
  if (showFront) {
    metalGrad.addColorStop(0, p.light);
    metalGrad.addColorStop(0.3, p.primary);
    metalGrad.addColorStop(0.7, p.secondary);
    metalGrad.addColorStop(1, p.dark);
  } else {
    metalGrad.addColorStop(0, p.secondary);
    metalGrad.addColorStop(0.4, p.primary);
    metalGrad.addColorStop(0.75, p.secondary);
    metalGrad.addColorStop(1, p.dark);
  }
  ctx.fillStyle = metalGrad;
  ctx.ellipse(cx, cy, rx, ryActual, 0, 0, TAU);
  ctx.fill();

  // Inner rim ring
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx * 0.92, ryActual * 0.92, 0, 0, TAU);
  ctx.strokeStyle = showFront ? p.light : p.secondary;
  ctx.globalAlpha = 0.35;
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.globalAlpha = 1;

  ctx.beginPath();
  ctx.ellipse(cx, cy, rx * 0.88, ryActual * 0.88, 0, 0, TAU);
  ctx.strokeStyle = showFront ? p.dark : p.dark;
  ctx.globalAlpha = 0.4;
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Scale text/graphics by rx (horizontal squash)
  const xScale = rx / R;
  const yScale = ryActual / R;

  if (showFront) {
    drawFrontFace(ctx, cx, cy, R, xScale, yScale, p);
  } else {
    drawBackFace(ctx, cx, cy, R, xScale, yScale, p);
  }

  ctx.restore();
}

function drawFrontFace(ctx, cx, cy, R, xScale, yScale, p) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(xScale, yScale);

  // Central emblem: a hexagonal token emblem
  const embR = R * 0.45;

  // Outer hexagon
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU - Math.PI / 6;
    const x = Math.cos(a) * embR;
    const y = Math.sin(a) * embR;
    if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
  }
  ctx.closePath();
  ctx.strokeStyle = p.light;
  ctx.lineWidth = 3.5 / xScale;
  ctx.globalAlpha = 0.7;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Inner hexagon
  const inner = embR * 0.72;
  ctx.beginPath();
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU - Math.PI / 6;
    ctx.lineTo(Math.cos(a) * inner, Math.sin(a) * inner);
  }
  ctx.closePath();
  ctx.strokeStyle = p.secondary;
  ctx.lineWidth = 1.5 / xScale;
  ctx.globalAlpha = 0.5;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // W monogram in center
  ctx.font = `bold ${R * 0.32}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Embossed effect: shadow below, highlight above
  ctx.fillStyle = p.dark;
  ctx.globalAlpha = 0.6;
  ctx.fillText('W', 1.5/xScale, 2/yScale);
  ctx.globalAlpha = 1;

  const textGrad = ctx.createLinearGradient(0, -R*0.12, 0, R*0.12);
  textGrad.addColorStop(0, p.light);
  textGrad.addColorStop(0.5, p.primary);
  textGrad.addColorStop(1, p.secondary);
  ctx.fillStyle = textGrad;
  ctx.fillText('W', 0, 0);

  // "WASTED TOKEN MINT" arc text
  ctx.font = `${R * 0.085}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  const arcR = R * 0.73;
  const text = 'WASTED  TOKEN  MINT';
  const chars = text.split('');
  const totalAngle = Math.PI * 0.9;
  const startAngle = -Math.PI / 2 - totalAngle / 2;
  const charAngle = totalAngle / (chars.length - 1);

  chars.forEach((ch, i) => {
    const a = startAngle + i * charAngle;
    ctx.save();
    ctx.rotate(a + Math.PI / 2);
    ctx.translate(0, -arcR);
    ctx.rotate(-Math.PI / 2);

    ctx.fillStyle = p.dark;
    ctx.globalAlpha = 0.5;
    ctx.fillText(ch, 0.8/xScale, 1/yScale);

    ctx.globalAlpha = 1;
    ctx.fillStyle = p.light;
    ctx.fillText(ch, 0, 0);

    ctx.restore();
  });

  // Bottom arc: EST. 2019
  const botText = 'EST.  2019';
  const botChars = botText.split('');
  const botAngle = Math.PI * 0.55;
  const botStart = Math.PI / 2 - botAngle / 2;
  const botCharAngle = botAngle / (botChars.length - 1);

  botChars.forEach((ch, i) => {
    const a = botStart + i * botCharAngle;
    ctx.save();
    ctx.rotate(a - Math.PI / 2);
    ctx.translate(0, arcR);
    ctx.rotate(Math.PI / 2);

    ctx.fillStyle = p.dark;
    ctx.globalAlpha = 0.4;
    ctx.fillText(ch, 0.8/xScale, 1/yScale);

    ctx.globalAlpha = 1;
    ctx.fillStyle = p.secondary;
    ctx.fillText(ch, 0, 0);

    ctx.restore();
  });

  // Small decorative stars/dots
  ctx.globalAlpha = 0.7;
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * TAU;
    const sr = R * 0.58;
    const sx = Math.cos(a) * sr;
    const sy = Math.sin(a) * sr;
    drawStar(ctx, sx, sy, 4/xScale, 3, p.light, p.secondary);
  }
  ctx.globalAlpha = 1;

  ctx.restore();
}

function drawBackFace(ctx, cx, cy, R, xScale, yScale, p) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(xScale, yScale);

  // Token denomination display
  // Central large number
  ctx.font = `bold ${R * 0.28}px Georgia, serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  // Embossed shadow
  ctx.fillStyle = p.dark;
  ctx.globalAlpha = 0.6;
  ctx.fillText('10,000', 2/xScale, -R*0.08 + 2/yScale);
  ctx.globalAlpha = 1;

  const numGrad = ctx.createLinearGradient(0, -R*0.2, 0, R*0.05);
  numGrad.addColorStop(0, p.light);
  numGrad.addColorStop(0.6, p.primary);
  numGrad.addColorStop(1, p.secondary);
  ctx.fillStyle = numGrad;
  ctx.fillText('10,000', 0, -R*0.08);

  // TOKENS label
  ctx.font = `${R * 0.12}px Georgia, serif`;
  ctx.letterSpacing = '0.2em';

  ctx.fillStyle = p.dark;
  ctx.globalAlpha = 0.5;
  ctx.fillText('TOKENS', 1.5/xScale, R*0.14 + 1.5/yScale);
  ctx.globalAlpha = 1;

  ctx.fillStyle = p.light;
  ctx.fillText('TOKENS', 0, R*0.14);

  // Decorative double ring
  ctx.beginPath();
  ctx.arc(0, 0, R * 0.82, 0, TAU);
  ctx.strokeStyle = p.secondary;
  ctx.lineWidth = 2 / xScale;
  ctx.globalAlpha = 0.4;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(0, 0, R * 0.78, 0, TAU);
  ctx.strokeStyle = p.light;
  ctx.lineWidth = 1 / xScale;
  ctx.globalAlpha = 0.3;
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Serial number at bottom
  ctx.font = `${R * 0.065}px 'Courier New', monospace`;
  ctx.fillStyle = p.secondary;
  ctx.globalAlpha = 0.7;
  ctx.fillText('#WT-00001', 0, R * 0.52);
  ctx.globalAlpha = 1;

  // "WASTED TOKEN MINT" small at top
  ctx.font = `${R * 0.065}px Georgia, serif`;
  ctx.fillStyle = p.secondary;
  ctx.globalAlpha = 0.7;
  ctx.fillText('WASTED TOKEN MINT', 0, -R * 0.55);
  ctx.globalAlpha = 1;

  // Small horizontal rule lines
  ctx.beginPath();
  ctx.moveTo(-R * 0.25, -R * 0.48);
  ctx.lineTo(R * 0.25, -R * 0.48);
  ctx.strokeStyle = p.secondary;
  ctx.lineWidth = 1 / xScale;
  ctx.globalAlpha = 0.5;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(-R * 0.35, R * 0.28);
  ctx.lineTo(R * 0.35, R * 0.28);
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Corner rosettes
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * TAU + TAU/8;
    const dr = R * 0.62;
    drawStar(ctx, Math.cos(a)*dr, Math.sin(a)*dr, 5/xScale, 3, p.light, p.secondary);
  }

  ctx.restore();
}

function drawSpecular(ctx, cx, cy, R, rx, ryActual, yaw, pitch) {
  ctx.save();
  ctx.beginPath();
  ctx.ellipse(cx, cy, rx, ryActual, 0, 0, TAU);
  ctx.clip();

  // Specular highlight: moves across coin as it rotates
  // Position derived from yaw so it's deterministic
  const specX = cx + Math.sin(yaw) * rx * 0.55;
  const specY = cy - ryActual * 0.2 + Math.sin(pitch) * ryActual * 0.3;

  const specW = rx * 0.45;
  const specH = ryActual * 0.6;

  const specGrad = ctx.createRadialGradient(specX, specY, 0, specX, specY, specW);
  specGrad.addColorStop(0, 'rgba(255,255,255,0.55)');
  specGrad.addColorStop(0.3, 'rgba(255,255,240,0.2)');
  specGrad.addColorStop(0.6, 'rgba(255,255,220,0.06)');
  specGrad.addColorStop(1, 'rgba(255,255,200,0)');

  ctx.fillStyle = specGrad;
  ctx.save();
  ctx.translate(specX, specY);
  ctx.scale(1, specH / specW);
  ctx.translate(-specX, -specY);
  ctx.beginPath();
  ctx.arc(specX, specY, specW, 0, TAU);
  ctx.fill();
  ctx.restore();

  // Secondary smaller hot-spot
  const spec2X = specX - rx * 0.15;
  const spec2Y = specY - ryActual * 0.25;
  const spec2G = ctx.createRadialGradient(spec2X, spec2Y, 0, spec2X, spec2Y, rx * 0.18);
  spec2G.addColorStop(0, 'rgba(255,255,255,0.35)');
  spec2G.addColorStop(0.5, 'rgba(255,255,255,0.08)');
  spec2G.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = spec2G;
  ctx.beginPath();
  ctx.arc(spec2X, spec2Y, rx * 0.18, 0, TAU);
  ctx.fill();

  ctx.restore();
}

function drawStar(ctx, x, y, r, points, color1, color2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const a = (i / (points * 2)) * TAU - Math.PI / 2;
    const rad = (i % 2 === 0) ? r : r * 0.45;
    const px = x + Math.cos(a) * rad;
    const py = y + Math.sin(a) * rad;
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.closePath();
  ctx.fillStyle = color1;
  ctx.globalAlpha = 0.85;
  ctx.fill();
  ctx.globalAlpha = 1;
}

function colorMult(hex, factor, alpha) {
  let r = parseInt(hex.slice(1,3), 16);
  let g = parseInt(hex.slice(3,5), 16);
  let b = parseInt(hex.slice(5,7), 16);
  r = clamp(Math.round(r * factor), 0, 255);
  g = clamp(Math.round(g * factor), 0, 255);
  b = clamp(Math.round(b * factor), 0, 255);
  return `rgba(${r},${g},${b},${alpha})`;
}

// ---------- ANIMATION LOOP ----------
function animLoop(ts) {
  if (!animRunning) return;
  if (!startTime) startTime = ts;
  const elapsed = (ts - startTime) % LOOP_DURATION;
  const t = elapsed / LOOP_DURATION;
  renderAtT(t);
  requestAnimationFrame(animLoop);
}

requestAnimationFrame(animLoop);

// ---------- PUBLIC API ----------
window.demo = {
  canvas: heroCanvas,
  setTime(t) {
    t = ((t % 1) + 1) % 1; // wrap to [0,1]
    renderAtT(t);
  },
  pause() {
    animRunning = false;
  }
};

// ---------- EDITION COINS ----------
function renderEditionCoins() {
  const editions = document.querySelectorAll('.edition');
  editions.forEach(el => {
    const edition = el.dataset.edition;
    const canvas = el.querySelector('.edition-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    const R = W * 0.42;
    const cx = W / 2, cy = H / 2;

    // Pick a nice static angle per edition to show the face properly
    const angles = { bronze: 0.08, silver: 0.06, gold: 0.05, black: 0.07 };
    const yaw = angles[edition] || 0.07;
    const pitch = 0.1;

    drawCoin(ctx, cx, cy, R, yaw, pitch, edition);

    // Animate edition coins with a slow spin
    let t0 = null;
    const duration = 5000 + Math.random() * 2000;
    const offset = Math.random();

    function loop(ts) {
      if (!t0) t0 = ts;
      const t = ((ts - t0) / duration + offset) % 1;
      const yA = t * TAU;
      const pA = Math.sin(t * TAU) * 0.18;
      drawCoin(ctx, cx, cy, R, yA, pA, edition);
      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  });
}

renderEditionCoins();

})();
</script>
